// Web pages -> single-file MHTML; PDFs -> original bytes (research.md #4/#5).
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { chromium } from 'playwright';
import { SNAPSHOT_DIR, THUMBNAIL_DIR, FAVICON_DIR } from '../db.js';
import { extractMetadata } from './metadata.js';

const NAV_TIMEOUT = 20000;

function extFromContentType(ct, fallback) {
  if (!ct) return fallback;
  if (ct.includes('png')) return '.png';
  if (ct.includes('jpeg') || ct.includes('jpg')) return '.jpg';
  if (ct.includes('gif')) return '.gif';
  if (ct.includes('svg')) return '.svg';
  if (ct.includes('webp')) return '.webp';
  if (ct.includes('x-icon') || ct.includes('vnd.microsoft.icon')) return '.ico';
  return fallback;
}

// Download a binary asset into `dir`; returns the stored filename or null.
async function downloadAsset(url, dir, defaultExt) {
  if (!url) return null;
  try {
    const res = await fetch(url, { redirect: 'follow', signal: AbortSignal.timeout(NAV_TIMEOUT) });
    if (!res.ok) return null;
    const buf = Buffer.from(await res.arrayBuffer());
    if (buf.length === 0) return null;
    const ext = extFromContentType(res.headers.get('content-type'), defaultExt);
    const name = `${crypto.randomUUID()}${ext}`;
    fs.writeFileSync(path.join(dir, name), buf);
    return name;
  } catch {
    return null;
  }
}

// Inspect the target's content type without committing to a full render.
async function detectContentType(address) {
  try {
    const res = await fetch(address, { method: 'GET', redirect: 'follow', signal: AbortSignal.timeout(NAV_TIMEOUT) });
    const ct = (res.headers.get('content-type') || '').toLowerCase();
    if (ct.includes('application/pdf')) {
      const buf = Buffer.from(await res.arrayBuffer());
      return { type: 'pdf', buf };
    }
    // Not a PDF; drain is unnecessary, let it be GC'd.
    return { type: 'html' };
  } catch {
    // Fall back to extension hint.
    if (/\.pdf($|\?)/i.test(address)) return { type: 'pdf-unfetched' };
    return { type: 'html' };
  }
}

// Main entry: returns a details bundle for Bookmark.create().
// Never throws; missing pieces degrade to null/false (FR-005/FR-008).
export async function capturePage(address) {
  const details = {
    title: '',
    description: '',
    faviconPath: null,
    previewImagePath: null,
    snapshotPath: null,
    snapshotType: null,
    snapshotAvailable: false,
  };

  const detected = await detectContentType(address);

  // --- PDF branch: preserve original bytes as the snapshot (FR-007) ---
  if (detected.type === 'pdf' || detected.type === 'pdf-unfetched') {
    let buf = detected.buf;
    if (!buf && detected.type === 'pdf-unfetched') {
      try {
        const res = await fetch(address, { redirect: 'follow', signal: AbortSignal.timeout(NAV_TIMEOUT) });
        if (res.ok) buf = Buffer.from(await res.arrayBuffer());
      } catch {
        /* leave buf undefined */
      }
    }
    if (buf && buf.length > 0) {
      const name = `${crypto.randomUUID()}.pdf`;
      fs.writeFileSync(path.join(SNAPSHOT_DIR, name), buf);
      details.snapshotPath = name;
      details.snapshotType = 'pdf';
      details.snapshotAvailable = true;
    }
    details.faviconPath = await downloadAsset(new URL('/favicon.ico', address).toString(), FAVICON_DIR, '.ico');
    return details;
  }

  // --- Web page branch: render, extract metadata, snapshot MHTML, thumbnail ---
  let browser;
  try {
    browser = await chromium.launch();
    const context = await browser.newContext();
    const page = await context.newPage();
    await page.goto(address, { waitUntil: 'load', timeout: NAV_TIMEOUT });

    const html = await page.content();
    const meta = extractMetadata(html, address);
    details.title = meta.title || '';
    details.description = meta.description || '';

    // Snapshot: single-file MHTML via CDP.
    try {
      const session = await context.newCDPSession(page);
      const { data } = await session.send('Page.captureSnapshot', { format: 'mhtml' });
      if (data) {
        const name = `${crypto.randomUUID()}.mhtml`;
        fs.writeFileSync(path.join(SNAPSHOT_DIR, name), data);
        details.snapshotPath = name;
        details.snapshotType = 'webpage';
        details.snapshotAvailable = true;
      }
    } catch {
      /* snapshot unavailable */
    }

    // Favicon.
    details.faviconPath = await downloadAsset(meta.favicon, FAVICON_DIR, '.ico');

    // Preview thumbnail: og:image if present, else a page screenshot.
    if (meta.previewImage) {
      details.previewImagePath = await downloadAsset(meta.previewImage, THUMBNAIL_DIR, '.png');
    }
    if (!details.previewImagePath) {
      try {
        const name = `${crypto.randomUUID()}.png`;
        await page.screenshot({ path: path.join(THUMBNAIL_DIR, name), fullPage: false });
        details.previewImagePath = name;
      } catch {
        /* thumbnail unavailable */
      }
    }
  } catch {
    // Page unreachable or render failed: keep whatever we have (FR-005).
  } finally {
    if (browser) await browser.close().catch(() => {});
  }

  return details;
}
// Parse page details from rendered HTML (research.md #3).
import { parse } from 'node-html-parser';

function attr(el, name) {
  return el ? el.getAttribute(name) : null;
}

// Resolve a possibly-relative URL against the page base.
function absolute(href, baseUrl) {
  if (!href) return null;
  try {
    return new URL(href, baseUrl).toString();
  } catch {
    return null;
  }
}

// Extract title, description, preview image, and favicon URL from HTML.
// Prefers OpenGraph/Twitter tags, falls back to standard tags.
export function extractMetadata(html, baseUrl) {
  const root = parse(html || '');

  const metaContent = (selector) => {
    const el = root.querySelector(selector);
    return el ? el.getAttribute('content') : null;
  };

  const ogTitle = metaContent('meta[property="og:title"]') || metaContent('meta[name="og:title"]');
  const twTitle = metaContent('meta[name="twitter:title"]');
  const docTitle = root.querySelector('title')?.text?.trim();
  const title = (ogTitle || twTitle || docTitle || '').trim();

  const ogDesc =
    metaContent('meta[property="og:description"]') || metaContent('meta[name="og:description"]');
  const twDesc = metaContent('meta[name="twitter:description"]');
  const metaDesc = metaContent('meta[name="description"]');
  const description = (ogDesc || twDesc || metaDesc || '').trim();

  const ogImage =
    metaContent('meta[property="og:image"]') || metaContent('meta[name="og:image"]');
  const twImage = metaContent('meta[name="twitter:image"]');
  const previewImage = absolute(ogImage || twImage, baseUrl);

  // Favicon: prefer explicit link rels, fall back to /favicon.ico.
  let faviconHref =
    attr(root.querySelector('link[rel="icon"]'), 'href') ||
    attr(root.querySelector('link[rel="shortcut icon"]'), 'href') ||
    attr(root.querySelector('link[rel="apple-touch-icon"]'), 'href');
  let favicon = absolute(faviconHref, baseUrl);
  if (!favicon) favicon = absolute('/favicon.ico', baseUrl);

  return { title, description, previewImage, favicon };
}
// Import/export the standard Netscape bookmark HTML format (research.md #7).

function decodeEntities(s) {
  return String(s || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'");
}

// Parse a Netscape bookmark file into { address, title, tags[] } entries.
// Token/line-based to tolerate the format's unclosed tags. Folder <H3> names and
// any TAGS="" attribute both map to tags (FR-020).
export function parseNetscape(html) {
  const entries = [];
  const folderStack = [];
  let pendingFolder = null;

  // Match, in document order: <H3>…</H3>, <A …>…</A>, <DL, or </DL>.
  const token = /<h3[^>]*>([\s\S]*?)<\/h3>|<a\s+([^>]*)>([\s\S]*?)<\/a>|(<dl)|(<\/dl>)/gi;
  let m;
  while ((m = token.exec(html || '')) !== null) {
    if (m[1] !== undefined) {
      // Folder heading; applies once its <DL> opens.
      pendingFolder = decodeEntities(m[1].replace(/<[^>]*>/g, '').trim());
    } else if (m[2] !== undefined) {
      // Anchor.
      const attrs = m[2];
      const hrefMatch = /href\s*=\s*"([^"]*)"/i.exec(attrs);
      if (hrefMatch) {
        const tagsMatch = /tags\s*=\s*"([^"]*)"/i.exec(attrs);
        const attrTags = tagsMatch
          ? tagsMatch[1].split(',').map((t) => decodeEntities(t.trim())).filter(Boolean)
          : [];
        const folders = folderStack.filter(Boolean);
        entries.push({
          address: decodeEntities(hrefMatch[1].trim()),
          title: decodeEntities(m[3].replace(/<[^>]*>/g, '').trim()),
          tags: [...new Set([...folders, ...attrTags])],
        });
      }
    } else if (m[4] !== undefined) {
      // <DL> opens a folder level; adopt the most recent heading if any.
      folderStack.push(pendingFolder);
      pendingFolder = null;
    } else if (m[5] !== undefined) {
      // </DL> closes the current level.
      folderStack.pop();
    }
  }

  return entries;
}

function escapeHtml(s) {
  return String(s || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Generate a Netscape bookmark HTML document from bookmark objects.
// Each bookmark's tags are emitted as TAGS="a,b" (browser-compatible) so that a
// round-trip preserves them (FR-021/SC-008).
export function generateNetscape(bookmarks) {
  const lines = [
    '<!DOCTYPE NETSCAPE-Bookmark-file-1>',
    '<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">',
    '<TITLE>Bookmarks</TITLE>',
    '<H1>Bookmarks</H1>',
    '<DL><p>',
  ];
  for (const b of bookmarks) {
    const added = Math.floor(new Date(b.createdAt || Date.now()).getTime() / 1000);
    const tagsAttr = b.tags && b.tags.length ? ` TAGS="${escapeHtml(b.tags.join(','))}"` : '';
    lines.push(
      `    <DT><A HREF="${escapeHtml(b.address)}" ADD_DATE="${added}"${tagsAttr}>${escapeHtml(
        b.title || b.address
      )}</A>`
    );
  }
  lines.push('</DL><p>');
  return lines.join('\n') + '\n';
}
